package com.farika.soundflow;
import android.content.*;import android.database.Cursor;import android.database.sqlite.*;import org.json.*;import java.io.*;import java.util.*;
/** Account-scoped disk snapshots. List rows never retain whole playlists in Java memory. */
public final class PlaylistCache {
 private final Context c;
 private static final class Store extends SQLiteOpenHelper {
  Store(Context c){super(c,"playlist_snapshots.db",null,1);}
  public void onCreate(SQLiteDatabase db){db.execSQL("CREATE TABLE snapshots (owner TEXT NOT NULL,id TEXT NOT NULL,kind TEXT NOT NULL,title TEXT NOT NULL,summary TEXT NOT NULL,body TEXT NOT NULL,source_ids TEXT NOT NULL,PRIMARY KEY(owner,id))");}
  public void onUpgrade(SQLiteDatabase db,int old,int next){}
 }
 public PlaylistCache(Context context){c=context.getApplicationContext();migrate();}
 private String owner(){return c.getSharedPreferences("profile",0).getString("id","");}
 private static void write(SQLiteDatabase db,String owner,String id,JSONObject j)throws Exception{JSONArray ids=new JSONArray(),tracks=j.optJSONArray("tracks");if(tracks!=null)for(int i=0;i<tracks.length();i++){JSONObject t=tracks.optJSONObject(i),remote=t==null?null:t.optJSONObject("remote");ids.put(remote==null?"":remote.optString("id"));}ContentValues v=new ContentValues();v.put("owner",owner);v.put("id",id);v.put("kind",j.optString("kind","own"));v.put("title",j.optString("title"));v.put("summary",ScApi.playlistSummary(j).toString());v.put("body",j.toString());v.put("source_ids",ids.toString());if(db.insertWithOnConflict("snapshots",null,v,SQLiteDatabase.CONFLICT_REPLACE)<0)throw new IOException("Не удалось сохранить список плейлиста");}
 /** Each legacy value is deleted only after the disk transaction commits, including other accounts. */
 private void migrate(){synchronized(PlaylistCache.class){SharedPreferences old=c.getSharedPreferences("playlist_snapshots",0);Map<String,?> entries=old.getAll();if(entries.isEmpty())return;ArrayList<String> moved=new ArrayList<>();try(Store helper=new Store(c)){SQLiteDatabase db=helper.getWritableDatabase();db.beginTransaction();try{for(Map.Entry<String,?> e:entries.entrySet()){int colon=e.getKey().indexOf(':');if(colon<1||!(e.getValue() instanceof String))continue;JSONObject j;try{j=new JSONObject((String)e.getValue());}catch(JSONException ignored){continue;}String user=e.getKey().substring(0,colon),id=e.getKey().substring(colon+1);try(Cursor row=db.rawQuery("SELECT 1 FROM snapshots WHERE owner=? AND id=?",new String[]{user,id})){if(!row.moveToFirst())write(db,user,id,j);}moved.add(e.getKey());}db.setTransactionSuccessful();}finally{db.endTransaction();}SharedPreferences.Editor edit=old.edit();for(String key:moved)edit.remove(key);edit.commit();}catch(Exception ignored){/* Keep the old data intact if migration fails. */}}}
 private String read(String id,String column){synchronized(PlaylistCache.class){try(Store helper=new Store(c)){SQLiteDatabase db=helper.getReadableDatabase();String[] args={owner(),id};if("body".equals(column)){int length;try(Cursor row=db.rawQuery("SELECT length(body) FROM snapshots WHERE owner=? AND id=?",args)){if(!row.moveToFirst())return null;length=row.getInt(0);}StringBuilder value=new StringBuilder(length);for(int offset=1;offset<=length;offset+=65536)try(Cursor chunk=db.rawQuery("SELECT substr(body,?,65536) FROM snapshots WHERE owner=? AND id=?",new String[]{String.valueOf(offset),args[0],args[1]})){if(!chunk.moveToFirst())return null;value.append(chunk.getString(0));}return value.toString();}try(Cursor row=db.query("snapshots",new String[]{column},"owner=? AND id=?",args,null,null,null)){return row.moveToFirst()?row.getString(0):null;}}}}
 public boolean contains(String id){return read(id,"id")!=null;}
 public JSONObject get(String id){String raw=read(id,"body");try{return raw==null?null:new JSONObject(raw);}catch(JSONException e){return null;}}
 public void put(String id,String title,String kind,List<Library.Track> tracks,boolean requested,String expectedOwner)throws Exception{synchronized(PlaylistCache.class){if(expectedOwner.isEmpty()||!expectedOwner.equals(owner()))throw new IOException("Аккаунт изменился");String raw=read(id,"summary");JSONObject old=raw==null?null:new JSONObject(raw);JSONArray a=new JSONArray();for(Library.Track t:tracks)a.put(Library.json(t));JSONObject j=new JSONObject().put("id",id).put("title",title).put("kind",kind).put("tracks",a).put("track_count",a.length()).put("cached",true).put("requested",requested||old!=null&&old.optBoolean("requested")).put("savedAt",System.currentTimeMillis());try(Store helper=new Store(c)){write(helper.getWritableDatabase(),expectedOwner,id,j);}}}
 public ArrayList<Library.Track> tracks(String id){ArrayList<Library.Track> out=new ArrayList<>();JSONObject j=get(id);if(j!=null){JSONArray a=j.optJSONArray("tracks");if(a!=null)for(int i=0;i<a.length();i++)if(a.optJSONObject(i)!=null)out.add(Library.fromJson(a.optJSONObject(i)));}return out;}
 public ArrayList<JSONObject> list(String kind){ArrayList<JSONObject> out=new ArrayList<>();if(owner().isEmpty())return out;try(Store helper=new Store(c);Cursor rows=helper.getReadableDatabase().query("snapshots",new String[]{"summary"},"owner=? AND kind=?",new String[]{owner(),kind},null,null,"title COLLATE NOCASE")){while(rows.moveToNext())try{out.add(new JSONObject(rows.getString(0)));}catch(JSONException ignored){}}return out;}
 public String progress(String id,Set<String> ready){String raw=read(id,"source_ids");int count=0,total=0;try{JSONArray ids=new JSONArray(raw==null?"[]":raw);total=ids.length();for(int i=0;i<total;i++)if(ready.contains(ids.optString(i)))count++;}catch(JSONException ignored){}return count+" / "+total+" на устройстве";}
 public void clearAll(){synchronized(PlaylistCache.class){try(Store helper=new Store(c)){helper.getWritableDatabase().delete("snapshots",null,null);}c.getSharedPreferences("playlist_snapshots",0).edit().clear().commit();}}
}
